--- a/src/utils/array.ts
+++ b/src/utils/array.ts
@@ -34,0 +35,15 @@ export function toArray<T>(items: ArrayLike<T>): T[] {
+
+/**
+ * Splits `items` into consecutive groups of at most `size` elements.
+ * @throws RangeError if `size` is not a positive integer.
+ */
+export function chunk<T>(items: readonly T[], size: number): T[][] {
+    if (size <= 0 || !Number.isInteger(size)) {
+        throw new RangeError(`Invalid size: ${size}`);
+    }
+    const results: T[][] = [];
+    for (let i = 0; i < items.length; i += size) {
+        results.push(Array.from(items.slice(i, i + size)));
+    }
+    return results;
+}
diff --git a/tests/unit/utils/array.tests.ts b/tests/unit/utils/array.tests.ts
